-- Load the colors generated by pywal
local colors = dofile(os.getenv("HOME") .. "/.config/hypr/colors-hyprland.lua")
local active_hex = colors.active:gsub("#", "")
local group_hex = colors.group:gsub("#", "")
local inactive_hex = colors.inactive:gsub("#", "")

-- Construct the table
local group_border_color = {
	colors = { "0xff" .. group_hex }, -- Prepends 0x for hex format if required
	angle = 45,
}

local active_border_color = {
	colors = { "0xff" .. active_hex }, -- Prepends 0x for hex format if required
	angle = 45,
}

local inactive_border_color = {
	colors = { "0xff" .. inactive_hex }, -- Prepends 0x for hex format if required
	angle = 45,
}

-- Configuration of hyprland
hl.config({
	general = {
		col = {
			active_border = active_border_color,
			inactive_border = colors.inactive,
		},
		border_size = 2,
		gaps_in = 0,
		gaps_out = 0,
		resize_on_border = false,
		allow_tearing = false,
		-- focus_new_on_workspace_switch = true,
		layout = "lua:blackarch";
	},
  render = {
        direct_scanout = false, -- Helps avoid occlusion capture bugs on some GPUs
    }
})

-- Group Configuration
hl.config({
	group = {
		insert_after_current = false,
		col = {
			border_active = group_border_color,
			border_inactive = inactive_border_color,
		},
		groupbar = { enabled = false, render_titles = false },
	},
})
hl.config({
	decoration = {
		rounding = 33,
		rounding_power = 9,
		blur = { enabled = true, size = 1, passes = 1 },
		shadow = { enabled = true, range = 4, render_power = 3, color = colors.inactive },
	},

	animations = {
		enabled = false,
		bezier = { "myBezier", 0.05, 0.9, 0.1, 1.05 },
		animation = {
			{ "windows", 1, 7, "myBezier" },
			{ "windowsOut", 1, 7, "default", "popin 80%" },
			{ "border", 1, 10, "default" },
			{ "fade", 1, 7, "default" },
			{ "workspaces", 1, 6, "default" },
		},
	},
})

hl.config({
	dwindle = {	preserve_split = true, force_split = 2 },
	scrolling = { fullscreen_on_one_column = true, column_width = 0.25, 0.49, 0.8, 1},
	master = { new_status = "slave", new_on_top = true },
	misc = {
		disable_hyprland_logo = true,
    force_default_wallpaper = 0,
		disable_splash_rendering = true,
		disable_scale_notification = true,
		focus_on_activate = true,
		anr_missed_pings = 3,
		on_focus_under_fullscreen = 1,
	},

	cursor = {
		hide_on_key_press = true,
		warp_on_change_workspace = 1,
	},

	binds = {
		hide_special_on_workspace_change = true,
	},
})

-- Default curves and animations, see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
hl.curve("easeOutQuint", { type = "bezier", points = { { 0.23, 1 }, { 0.32, 1 } } })
hl.curve("easeInOutCubic", { type = "bezier", points = { { 0.65, 0.05 }, { 0.36, 1 } } })
hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })
hl.curve("almostLinear", { type = "bezier", points = { { 0.5, 0.5 }, { 0.75, 1 } } })
hl.curve("quick", { type = "bezier", points = { { 0.15, 0 }, { 0.1, 1 } } })

-- Default springs
hl.curve("easy", { type = "spring", mass = 1, stiffness = 71.2633, dampening = 15.8273644 })

hl.animation({ leaf = "global", enabled = true, speed = 10, bezier = "default" })
hl.animation({ leaf = "border", enabled = true, speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows", enabled = true, speed = 4.79, spring = "easy" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 4.1, spring = "easy", style = "popin 87%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.49, bezier = "linear", style = "popin 87%" })
hl.animation({ leaf = "fadeIn", enabled = true, speed = 1.73, bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut", enabled = true, speed = 1.46, bezier = "almostLinear" })
hl.animation({ leaf = "fade", enabled = true, speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers", enabled = true, speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn", enabled = true, speed = 4, bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut", enabled = true, speed = 1.5, bezier = "linear", style = "fade" })
hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = 1.79, bezier = "almostLinear" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 1.39, bezier = "almostLinear" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "workspacesIn", enabled = true, speed = 1.21, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "workspacesOut", enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "zoomFactor", enabled = true, speed = 7, bezier = "quick" })
